// Textes de l'outil DNS (FR/EN) : interface, titres des vérifications et message de chaque constat.
// Un constat est identifié par un code (voir src/lib/dns/*) ; ses paramètres s'insèrent dans {accolades}.
// tests/unit/dns-tool.test.js vérifie que chaque code produit par l'analyse est traduit dans les deux langues.

const m = (title, detail, fix) => ({ title, detail, fix });

/** Remplace {param} par sa valeur ; un paramètre absent laisse la place vide. */
export const fill = (text, params = {}) => (text ?? '').replace(/\{(\w+)\}/g, (_, key) => String(params[key] ?? ''));

/** Titre, détail et correction d'un constat dans la langue demandée (repli sur le code lui-même si inconnu). */
export function describeFinding(lang, finding) {
  const entry = DNS_TOOL[lang].messages[finding.code];
  if (!entry) return { title: finding.code, detail: '', fix: '' };
  return { title: fill(entry.title, finding.params), detail: fill(entry.detail, finding.params), fix: fill(entry.fix, finding.params) };
}

